function UISoundPlayer:OnSkip()
    print("结束了")
    KTool.SafeDelete(self.controller.gameObject)
    if self.finishCb  then
        self.finishCb()
    end
end

--暂停
function UISoundPlayer:Pause()
    self.Node:Pause()
end

---Unpause the paused playback of this AudioSource.
function UISoundPlayer:UnPause()
    self.Node:UnPause()
end

--播放
function UISoundPlayer:Play()
    self.Node:Play()
end

---Playback position in seconds.
---@return number 当前播放的时间，单位:秒
function UISoundPlayer:GetTime()
    return checkInt(self.Node.time)
end

---@return number 音频长度，单位:秒
function UISoundPlayer:GetLength()
    if self.Node.clip then
        return checkInt(self.Node.clip.length / self.Node.clip.channels)
    end
    return nil
end

function UISoundPlayer:OnDestroy()
    if not isNull(self.loader) then
        self.loader:Release()
        self.loader = nil
    end
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UISoundPlayer